<?php
declare(strict_types=1);require_once __DIR__.'/common.php';$user=qa_require_user();qa_post();$id=(int)($_POST['id']??0);$pdo=db();$st=$pdo->prepare('SELECT a.question_id,q.solved_answer_id FROM qa_answers a JOIN qa_questions q ON q.id=a.question_id WHERE a.id=? AND a.user_id=?');$st->execute([$id,(int)$user['id']]);$row=$st->fetch();if(!$row)exit('Not allowed.');$qid=(int)$row['question_id'];$pdo->beginTransaction();try{if((int)$row['solved_answer_id']===$id)$pdo->prepare('UPDATE qa_questions SET is_solved=0,solved_answer_id=NULL WHERE id=?')->execute([$qid]);$files=$pdo->prepare('SELECT file_path FROM qa_attachments WHERE answer_id=?');$files->execute([$id]);foreach($files->fetchAll() as $f){$path=__DIR__.'/../../'.str_replace('dashboard/group-peer/','dashboard/group-peer/',$f['file_path']);if(is_file($path))@unlink($path);}$pdo->prepare('DELETE FROM qa_answers WHERE id=?')->execute([$id]);$pdo->commit();}catch(Throwable $e){$pdo->rollBack();throw $e;}qa_redirect('view.php?id='.$qid);
